<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import UiButton from '@/components/ui/UiButton.vue'
import UiBadge from '@/components/ui/UiBadge.vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import UiPageState from '@/components/ui/UiPageState.vue'
import UiNotice from '@/components/ui/UiNotice.vue'
import OwnerField from '@/components/owner/OwnerField.vue'
import RemotePicker from '@/components/owner/RemotePicker.vue'
import { eventPayload, localEventTime, useOwnerApi } from '@/composables/useOwnerApi'
import { formatMoney } from '@/lib/format'
import { formatUnitPrice } from '@/lib/unit-price'
import { formatDateTime } from '@/lib/notifications'
import { toApiError } from '@/lib/api'
import type { Occupancy, ServicePeriod, Stay } from '@/types/owner'
type Action = 'members' | 'leave' | 'representative' | 'apply' | 'end' | 'transfer' | 'checkout'
const route = useRoute(), router = useRouter(), id = Number(route.params.id)
const { get, write, busy, error, errors, clearError } = useOwnerApi()
const stay = ref<Occupancy | null>(null), loading = ref(true), loadError = ref(''), notice = ref(route.query.received ? 'Đã nhận phòng. Hãy áp dụng các dịch vụ cần sử dụng cho đợt thuê này.' : '')
const action = ref<Action | ''>(''), reviewing = ref(false), selection = ref<number[]>([]), replacement = ref<number[]>([])
const member = ref<Stay | null>(null), period = ref<ServicePeriod | null>(null), eventAt = ref(localEventTime())
const serviceForm = reactive({ unit_price: '', unit: '', billing_method: 'per_room' })
const labels = reactive(new Map<number, string>()), clientError = ref('')
const titles: Record<Action, string> = { members: 'Thêm thành viên', leave: 'Thành viên rời phòng', representative: 'Đổi người đại diện', apply: 'Áp dụng / đổi giá dịch vụ', end: 'Ngừng dịch vụ', transfer: 'Chuyển cả nhóm', checkout: 'Trả phòng' }
const activeMembers = computed(() => stay.value?.members?.filter(item => item.is_active) ?? [])
const activeRep = computed(() => stay.value?.representatives?.find(item => item.is_active))
const allowedRepresentatives = computed(() => activeMembers.value.filter(item => item.tenant_id !== (action.value === 'leave' ? member.value?.tenant_id : undefined)).map(item => item.tenant_id))
const eventKey = computed(() => ({ members: 'moved_in_at', leave: 'moved_out_at', representative: 'started_at', apply: 'effective_from', end: 'effective_until', transfer: 'transferred_at', checkout: 'ended_at' })[action.value as Action] ?? '')
async function load() {
  stay.value = null; loading.value = true; loadError.value = ''
  try { stay.value = (await get<{ data: Occupancy }>(`/occupancies/${id}`)).data }
  catch (caught) { loadError.value = toApiError(caught).message }
  finally { loading.value = false }
}
function open(value: Action, selected?: Stay | ServicePeriod) {
  action.value = value; reviewing.value = false; clearError(); clientError.value = ''; labels.clear(); selection.value = []; replacement.value = []; eventAt.value = localEventTime()
  member.value = value === 'leave' ? selected as Stay : null
  period.value = value === 'end' ? selected as ServicePeriod : null
  Object.assign(serviceForm, { unit_price: '', unit: '', billing_method: 'per_room' })
}
function choose(value: Record<string, unknown>) {
  labels.set(Number(value.id), String(value.full_name ?? value.room_number ?? value.name ?? ''))
  if (action.value === 'apply') Object.assign(serviceForm, { unit_price: String(value.default_unit_price), unit: String(value.unit), billing_method: String(value.billing_method) })
}
function close() { if (!busy.value) { action.value = ''; clearError(); clientError.value = '' } }
function review() {
  clientError.value = ''
  if (['members', 'representative', 'apply', 'transfer'].includes(action.value) && !selection.value.length) { clientError.value = 'Hãy chọn thông tin cần áp dụng.'; return }
  if (action.value === 'members' && activeMembers.value.length + selection.value.length > (stay.value?.room.capacity ?? 0)) { clientError.value = 'Số thành viên vượt sức chứa phòng.'; return }
  if (action.value === 'leave' && activeMembers.value.length <= 1) { clientError.value = 'Thành viên cuối cùng cần dùng thao tác Trả phòng.'; return }
  if (action.value === 'leave' && activeRep.value?.tenant_stay_id === member.value?.id && !replacement.value.length) { clientError.value = 'Hãy chọn người đại diện thay thế trước khi thành viên này rời đi.'; return }
  reviewing.value = true; clearError()
}
async function submit() {
  if (!action.value || !stay.value) return
  const operation = action.value
  const endpoints: Record<Action, string> = { members: '/members', leave: `/members/${member.value?.id}/leave`, representative: '/representative', apply: '/services', end: `/services/${period.value?.id}/end`, transfer: '/transfer', checkout: '/checkout' }
  const payload: Record<string, unknown> = { [eventKey.value]: eventPayload(eventAt.value) }
  if (operation === 'members') payload.tenant_ids = [...selection.value]
  if (operation === 'representative') payload.tenant_id = selection.value[0]
  if (operation === 'leave' && replacement.value[0]) payload.replacement_tenant_id = replacement.value[0]
  if (operation === 'apply') Object.assign(payload, { service_id: selection.value[0], ...serviceForm })
  if (operation === 'transfer') payload.room_id = selection.value[0]
  try {
    const result = await write<{ data: Occupancy; message: string }>('post', `/occupancies/${id}${endpoints[operation]}`, payload)
    notice.value = result.message; close()
    if (operation === 'transfer') await router.replace(`/owner/stays/${result.data.id}`)
    else await load()
  } catch { /* Preserve review. Explicit correction/retry is required. */ }
}
void load()
</script>
<template><section class="management-page"><RouterLink class="back-link" to="/owner/stays">← Quá trình thuê</RouterLink><UiPageState v-if="loading" kind="loading" /><UiPageState v-else-if="loadError" kind="error" :description="loadError"><UiButton @click="load">Thử lại</UiButton></UiPageState><template v-else-if="stay"><header class="management-header"><div><span class="eyebrow">Nhóm {{ stay.group.group_code }}</span><h1>Đợt thuê phòng {{ stay.room.room_number }}</h1><p>{{ formatDateTime(stay.started_at) }} → {{ stay.ended_at ? formatDateTime(stay.ended_at) : 'Hiện tại' }}</p><UiBadge :tone="stay.is_active ? 'success' : 'neutral'">{{ stay.is_active ? 'Đang thuê' : 'Đã kết thúc' }}</UiBadge></div><div v-if="stay.is_active" class="button-row"><UiButton variant="secondary" @click="open('transfer')">Chuyển cả nhóm</UiButton><UiButton variant="danger" @click="open('checkout')">Trả phòng</UiButton></div></header><UiNotice v-if="notice" tone="success">{{ notice }}</UiNotice><div class="detail-sections"><section class="record-card"><h2>Thông tin đợt thuê</h2><dl class="record-facts"><div><dt>Giá toàn phòng / tháng đã chốt</dt><dd>{{ formatMoney(stay.monthly_rent) }}</dd></div><div><dt>Đang ở / Sức chứa</dt><dd>{{ stay.resident_count }} / {{ stay.room.capacity }} người</dd></div><div><dt>Đại diện hiện tại</dt><dd>{{ activeRep?.tenant.full_name ?? 'Chưa có' }}</dd></div></dl><div class="button-row"><RouterLink v-if="stay.previous_occupancy_id" class="record-link" :to="`/owner/stays/${stay.previous_occupancy_id}`">Đợt thuê trước</RouterLink><RouterLink v-if="stay.next_occupancy_id" class="record-link" :to="`/owner/stays/${stay.next_occupancy_id}`">Đợt thuê sau</RouterLink></div><p class="help-text">Giá này là của toàn phòng. Chuyển phòng giữ giá đã chốt và lịch sử; trả phòng giữ hóa đơn và công nợ.</p><div class="button-row"><RouterLink class="record-link" :to="{ path: '/owner/meters', query: { occupancy_id: stay.id } }">Điện nước</RouterLink><RouterLink class="record-link" :to="{ path: '/owner/invoices', query: { occupancy_id: stay.id } }">Hóa đơn</RouterLink></div></section><section class="record-card"><header class="button-row"><h2>Thành viên</h2><UiButton v-if="stay.is_active" variant="secondary" @click="open('members')">Thêm thành viên</UiButton></header><ul class="detail-items"><li v-for="item in stay.members" :key="item.id"><RouterLink class="record-link" :to="`/owner/tenants/${item.tenant_id}`">{{ item.tenant?.full_name }}</RouterLink><p class="help-text">{{ formatDateTime(item.moved_in_at) }} → {{ item.moved_out_at ? formatDateTime(item.moved_out_at) : 'Hiện tại' }}</p><UiBadge :tone="item.is_active ? 'success' : 'neutral'">{{ item.is_active ? 'Đang ở' : 'Đã rời' }}</UiBadge><div v-if="item.is_active && stay.is_active" class="button-row"><UiButton v-if="activeMembers.length > 1" variant="ghost" @click="open('leave', item)">Ghi rời phòng: {{ item.tenant?.full_name }}</UiButton><span v-else class="help-text">Thành viên cuối cùng: dùng Trả phòng để kết thúc.</span></div></li></ul></section><section class="record-card"><header class="button-row"><h2>Người đại diện</h2><UiButton v-if="stay.is_active" variant="secondary" @click="open('representative')">Chọn / đổi đại diện</UiButton></header><p class="help-text">Chỉ thành viên đang ở có tài khoản hoạt động được làm đại diện. Đổi đại diện không tự chuyển quyền hóa đơn cũ.</p><p v-if="!stay.representatives?.length" class="help-text">Chưa có đại diện.</p><ul class="detail-items"><li v-for="rep in stay.representatives" :key="rep.id"><strong>{{ rep.tenant.full_name }}</strong><p class="help-text">{{ formatDateTime(rep.started_at) }} → {{ rep.ended_at ? formatDateTime(rep.ended_at) : 'Hiện tại' }}</p><UiBadge :tone="rep.is_active ? 'success' : 'neutral'">{{ rep.is_active ? 'Đang đại diện' : 'Đã kết thúc' }}</UiBadge></li></ul></section><section class="record-card"><header class="button-row"><h2>Dịch vụ theo thời gian</h2><UiButton v-if="stay.is_active" variant="secondary" @click="open('apply')">Áp dụng / đổi giá dịch vụ</UiButton></header><p class="help-text">Mỗi khoảng giữ giá, đơn vị và cách tính đã chốt. Đổi giá sẽ đóng khoảng cũ và tạo khoảng mới.</p><p v-if="!stay.services?.length" class="help-text">Chưa áp dụng dịch vụ nào.</p><ul class="detail-items"><li v-for="service in stay.services" :key="service.id"><strong>{{ service.service.name }}</strong><p>{{ formatUnitPrice(service.unit_price) }} / {{ service.unit }} · {{ service.billing_method === 'metered' ? 'Theo chỉ số' : 'Theo phòng' }}</p><p class="help-text">{{ formatDateTime(service.effective_from) }} → {{ service.effective_until ? formatDateTime(service.effective_until) : 'Hiện tại' }}</p><UiBadge :tone="service.is_active ? 'success' : 'neutral'">{{ service.is_active ? 'Đang áp dụng' : 'Đã ngừng' }}</UiBadge><div v-if="service.is_active && stay.is_active" class="button-row"><UiButton variant="ghost" @click="open('end', service)">Ngừng {{ service.service.name }}</UiButton></div></li></ul></section></div><UiDialog :open="!!action" :title="action ? titles[action] : ''" @update:open="value => { if (!value) close() }"><form class="form-grid" @submit.prevent="reviewing ? submit() : review()"><p v-if="error || clientError" class="form-error" role="alert">{{ error || clientError }}</p><fieldset v-if="!reviewing" class="form-grid" :disabled="busy"><RemotePicker v-if="action === 'members'" v-model="selection" label="Thành viên bổ sung" path="/tenants" label-key="full_name" :filters="{ is_residing: 0 }" multiple @choose="choose" /><RemotePicker v-if="action === 'representative'" v-model="selection" label="Người đại diện mới" path="/tenants" label-key="full_name" :filters="{ is_residing: 1 }" :allowed-ids="allowedRepresentatives" require-account @choose="choose" /><template v-if="action === 'leave'"><p>Ghi nhận <strong>{{ member?.tenant?.full_name }}</strong> rời phòng.</p><RemotePicker v-if="activeRep?.tenant_stay_id === member?.id" v-model="replacement" label="Người đại diện thay thế" path="/tenants" label-key="full_name" :filters="{ is_residing: 1 }" :allowed-ids="allowedRepresentatives" require-account @choose="choose" /></template><template v-if="action === 'apply'"><RemotePicker v-model="selection" label="Dịch vụ áp dụng" path="/services" label-key="name" :filters="{ is_active: 1 }" @choose="choose" /><OwnerField v-model="serviceForm.unit_price" label="Đơn giá chốt (VNĐ)" name="unit_price" :errors="errors" required hint="Tối đa 4 chữ số thập phân; không dùng dấu phân cách hàng nghìn." /><OwnerField v-model="serviceForm.unit" label="Đơn vị chốt" name="unit" :errors="errors" :max-length="30" required /><label>Cách tính chốt<select v-model="serviceForm.billing_method" class="ui-select"><option value="per_room">Theo phòng</option><option value="metered">Theo chỉ số</option></select></label><p class="help-text">Đổi giá điện/nước giữa kỳ cần ghi chỉ số tại mốc đổi giá trước. Giá mới không sửa các khoảng quá khứ.</p></template><RemotePicker v-if="action === 'transfer'" v-model="selection" label="Phòng chuyển đến" path="/rooms" label-key="room_number" :filters="{ operational_status: 'available', occupancy_status: 'vacant' }" @choose="choose" /><p v-if="action === 'end'">Ngừng dịch vụ <strong>{{ period?.service.name }}</strong> từ thời điểm bên dưới.</p><p v-if="action === 'checkout'">Kết thúc đợt thuê, thành viên, đại diện và dịch vụ đang mở. Thao tác không tự lập hóa đơn cuối hoặc xóa công nợ.</p><OwnerField v-model="eventAt" label="Thời điểm thực hiện (giờ Việt Nam)" :name="eventKey" :errors="errors" type="datetime-local" step="1" :max="localEventTime()" required /></fieldset><div v-else class="review-box"><h3>Xem lại: {{ action ? titles[action] : '' }}</h3><p>Phòng {{ stay.room.room_number }} · Nhóm {{ stay.group.group_code }}</p><p v-if="selection.length">Lựa chọn: <strong>{{ selection.map(id => labels.get(id)).join(', ') }}</strong></p><p v-if="member">Thành viên rời đi: <strong>{{ member.tenant?.full_name }}</strong></p><p v-if="replacement.length">Đại diện thay thế: {{ labels.get(replacement[0]!) }}</p><p v-if="period">Dịch vụ ngừng: {{ period.service.name }}</p><p v-if="action === 'apply'">Giá chốt: {{ formatUnitPrice(serviceForm.unit_price) }} / {{ serviceForm.unit }} · {{ serviceForm.billing_method === 'metered' ? 'Theo chỉ số' : 'Theo phòng' }}</p><p>Thời điểm: <strong>{{ formatDateTime(eventPayload(eventAt)) }}</strong></p><p v-if="action === 'transfer'">Chuyển toàn bộ thành viên, đại diện và dịch vụ hiện hành sang phòng mới, giữ giá thuê đã chốt. Đồng hồ phòng mới cần chỉ số nền mới.</p><p v-if="action === 'checkout'">Đóng đợt thuê và các khoảng đang mở. Hóa đơn, thanh toán và công nợ vẫn được giữ lại.</p><p v-for="(messages, key) in errors" :key="key" class="field-error" role="alert">{{ messages[0] }}</p></div><div class="button-row"><UiButton v-if="reviewing" variant="secondary" :disabled="busy" @click="reviewing = false; clearError()">Chỉnh lại</UiButton><UiButton type="submit" :variant="reviewing && (action === 'checkout' || action === 'leave' || action === 'end') ? 'danger' : 'primary'" :loading="busy">{{ reviewing ? 'Xác nhận thực hiện' : 'Xem lại thao tác' }}</UiButton></div></form><template #actions><UiButton variant="secondary" :disabled="busy" @click="close">Đóng</UiButton></template></UiDialog></template></section></template>
